#include "mfcc.h"
#include "mfcc_data.h" // Generated by generate_tables.py
#include "kiss_fft.h"  // KissFFT library
#include <math.h>

// --- INTERNAL MEMORY (STATIC) ---
// Allocated once and kept in RAM for the lifetime of the program.
// Avoids repeated heap allocation during real-time inference.

static kiss_fft_cfg  fft_cfg;               // KissFFT configuration handle
static kiss_fft_cpx  fft_in[N_FFT];         // Input buffer  (complex: real + imaginary)
static kiss_fft_cpx  fft_out[N_FFT];        // Output buffer (complex: real + imaginary)
static float         fft_mag[N_FFT/2 + 1];  // POWER spectrum (N_FFT/2+1 real values)
static float         mel_energies[N_MELS];  // Log-Mel energy per band

// --------------------------------

void mfcc_init() {
    // Allocate the KissFFT configuration for a forward FFT of size N_FFT.
    // Arguments: (size, inverse_fft=0, mem=0, lenmem=0)
    fft_cfg = kiss_fft_alloc(N_FFT, 0, 0, 0);
}

void mfcc_free() {
    // Release KissFFT memory on shutdown.
    kiss_fft_free(fft_cfg);
}

void mfcc_compute(const float* audio_data, float* mfcc_out) {

    // ------------------------------------------------------------------
    // STEP 1: Windowing (Hamming window)
    // Multiplying by the window tapers the frame edges to zero.
    // This reduces spectral leakage in the FFT output.
    // ------------------------------------------------------------------
    for (int i = 0; i < N_FFT; i++) {
        fft_in[i].r = audio_data[i] * hamming_window[i];
        fft_in[i].i = 0.0f; // Audio is real; imaginary part is always 0
    }

    // ------------------------------------------------------------------
    // STEP 2: FFT (Fast Fourier Transform)
    // Converts the time-domain frame into the frequency domain.
    // ------------------------------------------------------------------
    kiss_fft(fft_cfg, fft_in, fft_out);

    // ------------------------------------------------------------------
    // STEP 3: POWER Spectrum  ← FIX: was sqrtf() (magnitude), now power
    // Power = Real^2 + Imag^2
    //
    // WHY: librosa.feature.melspectrogram() uses power=2.0 by default,
    // meaning it squares the magnitude.  We must do the same here or
    // every MFCC value will be half of what the model was trained on.
    //
    // We only need the first half (DC to Nyquist = N_FFT/2+1 bins).
    // ------------------------------------------------------------------
    for (int i = 0; i < N_FFT/2 + 1; i++) {
        float r  = fft_out[i].r;
        float im = fft_out[i].i;
        fft_mag[i] = r*r + im*im;   // Power (no sqrtf)
    }

    // ------------------------------------------------------------------
    // STEP 4: Mel Filterbank
    // Matrix multiply: mel_filters (N_MELS x N_FFT/2+1) x fft_mag
    // Groups the N_FFT/2+1 frequency bins into N_MELS perceptual bands.
    //
    // mel_filters is stored row-major (flattened 2D array):
    //   index = (row * row_width) + col
    //         = (i   * (N_FFT/2+1)) + j
    // ------------------------------------------------------------------
    const int SPEC_BINS = N_FFT/2 + 1; // 257

    for (int i = 0; i < N_MELS; i++) {
        float sum = 0.0f;
        for (int j = 0; j < SPEC_BINS; j++) {
            sum += fft_mag[j] * mel_filters[i * SPEC_BINS + j];
        }

        // STEP 5: Log compression
        // Humans perceive loudness on a log scale.
        // +1e-6 is a small floor to avoid log(0) = -infinity crash.
        mel_energies[i] = logf(sum + 1e-6f);
    }

    // ------------------------------------------------------------------
    // STEP 6: DCT (Discrete Cosine Transform)
    // Matrix multiply: dct_matrix (N_MFCC x N_MELS) x mel_energies
    // Decorrelates the mel-band energies and produces compact features.
    //
    // dct_matrix is stored row-major (flattened 2D array):
    //   index = (i * N_MELS) + j
    // ------------------------------------------------------------------
    for (int i = 0; i < N_MFCC; i++) {
        float sum = 0.0f;
        for (int j = 0; j < N_MELS; j++) {
            sum += mel_energies[j] * dct_matrix[i * N_MELS + j];
        }
        mfcc_out[i] = sum; // Final MFCC coefficient
    }
}